private Stream<MapResult> xmlXpathToMapResult(@Name("url") String url,
                                              boolean simpleMode,
                                              String path,
                                              Map<String, Object> config) throws Exception {
    if (config == null) {
        config = Collections.emptyMap();
    }
    boolean failOnError = (boolean) config.getOrDefault("failOnError", true);
    List<MapResult> result = new ArrayList<>();

    try {
        /* Securely configure the XML parser to guard against XXE */
        DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
        documentBuilderFactory.setNamespaceAware(true);
        documentBuilderFactory.setIgnoringElementContentWhitespace(true);

        // Disallow DOCTYPE declarations
        documentBuilderFactory.setFeature(
                "http://apache.org/xml/features/disallow-doctype-decl",
                true);

        // Disable loading of external DTDs and entities
        documentBuilderFactory.setFeature(
                "http://apache.org/xml/features/nonvalidating/load-external-dtd",
                false);
        documentBuilderFactory.setFeature(
                "http://xml.org/sax/features/external-general-entities",
                false);
        documentBuilderFactory.setFeature(
                "http://xml.org/sax/features/external-parameter-entities",
                false);

        // Prevent XInclude and entity expansion
        documentBuilderFactory.setXIncludeAware(false);
        documentBuilderFactory.setExpandEntityReferences(false);

        DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();

        FileUtils.checkReadAllowed(url);

        @SuppressWarnings("unchecked")
        Map<String, Object> headers = (Map<String, Object>) config.getOrDefault("headers", Collections.emptyMap());

        /* Use try‑with‑resources to ensure the input stream is closed */
        try (java.io.InputStream is = Util.openInputStream(url, headers, null)) {
            Document doc = documentBuilder.parse(is);

            XPathFactory xPathFactory = XPathFactory.newInstance();
            XPath xPath = xPathFactory.newXPath();

            path = StringUtils.isEmpty(path) ? "/" : path;
            XPathExpression xPathExpression = xPath.compile(path);
            NodeList nodeList = (NodeList) xPathExpression.evaluate(doc, XPathConstants.NODESET);

            for (int i = 0; i < nodeList.getLength(); i++) {
                Deque<Map<String, Object>> stack = new LinkedList<>();
                handleNode(stack, nodeList.item(i), simpleMode);
                while (!stack.isEmpty()) {
                    result.add(new MapResult(stack.pollFirst()));
                }
            }
        }
    } catch (FileNotFoundException e) {
        if (!failOnError) {
            return Stream.of(new MapResult(Collections.emptyMap()));
        }
        throw new FileNotFoundException(e.getMessage());
    } catch (Exception e) {
        if (!failOnError) {
            return Stream.of(new MapResult(Collections.emptyMap()));
        }
        throw new Exception(e);
    }

    return result.stream();
}
