public class MediaTypeHeaderDelegate implements RuntimeDelegate.HeaderDelegate {

    // ... other methods ...

    /**
     * Validates a media type component (major or subtype). According to RFC 7230,
     * a token consists of one or more characters from the set:
     *   !#$%&'*+-.^_`|~0-9A-Za-z
     * This method uses a whitelist regex to reject any control characters,
     * whitespace, or separator characters that could be used for header
     * injection (e.g., '/', '\\', ';', '\n', '\r', etc.).
     *
     * @param str the component to validate
     * @return {@code true} if the component is a valid token, {@code false} otherwise
