@Override
public ByteBuffer encode(final String name) {
    final CharsetEncoder enc = newEncoder();
    final CharBuffer cb = CharBuffer.wrap(name);
    CharBuffer tmp = null;
    ByteBuffer out = ByteBuffer.allocate(estimateInitialBufferSize(enc, cb.remaining()));

    // Track progress to avoid infinite loops on malformed/unmappable input
    int lastPosition = -1;
    int retryCounter = 0;
    final int MAX_RETRIES = 1000; // arbitrary safe upper bound

    while (cb.remaining() > 0) {
        int posBefore = cb.position();
        CoderResult res = enc.encode(cb, out, false);

        // Handle overflow by growing the output buffer
        if (res.isOverflow()) {
            int increment = estimateIncrementalEncodingSize(enc, cb.remaining());
            out = ZipEncodingHelper.growBufferBy(out, increment);
            continue; // retry encoding after buffer growth
        }

        // If we made no progress and encountered a malformed/unmappable sequence,
        // replace it with the Unicode replacement character to guarantee termination.
        if ((res.isMalformed() || res.isUnmappable()) && cb.position() == posBefore) {
            if (++retryCounter > MAX_RETRIES) {
                throw new IllegalArgumentException("Too many malformed/unmappable characters");
            }
            // Encode U+FFFD replacement character
            CharBuffer repl = CharBuffer.wrap(new char[] { '\uFFFD' });
            enc.encode(repl, out, false);
            // Advance the original buffer by one character to avoid re‑processing
            cb.position(cb.position() + 1);
            continue;
        }

        // Reset retry counter on successful progress
        if (cb.position() > posBefore) {
            retryCounter = 0;
        }

        // Handle malformed/unmappable sequences that do consume input
        if (res.isMalformed() || res.isUnmappable()) {
            int spaceForSurrogate = estimateIncrementalEncodingSize(enc, 6 * res.length());
            if (spaceForSurrogate > out.remaining()) {
                int charCount = 0;
                for (int i = cb.position(); i < cb.limit(); i++) {
                    charCount += !enc.canEncode(cb.get(i)) ? 6 : 1;
                }
                int totalExtraSpace = estimateIncrementalEncodingSize(enc, charCount);
                out = ZipEncodingHelper.growBufferBy(out, totalExtraSpace - out.remaining());
            }
            if (tmp == null) {
                tmp = CharBuffer.allocate(6);
            }
            for (int i = 0; i < res.length(); ++i) {
                out = encodeFully(enc, encodeSurrogate(tmp, cb.get()), out);
            }
        }
    }

    // Final flush of the encoder
    CoderResult finalRes = enc.encode(cb, out, true);
    if (finalRes.isError()) {
        // If the final flush still reports an error, replace with U+FFFD
        CharBuffer repl = CharBuffer.wrap(new char[] { '\uFFFD' });
        enc.encode(repl, out, true);
    }

    out.limit(out.position());
    out.rewind();
    return out;
}
